script=r'''
const $=id=>document.getElementById(id);
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const lessons=[...document.querySelectorAll('.lesson')];
const validIds=new Set(lessons.map(el=>el.id));
let completed={};try{const stored=JSON.parse(localStorage.getItem('atlas-course-progress-v1')||'{}');if(stored&&typeof stored==='object'&&!Array.isArray(stored)){for(const id of validIds)completed[id]=stored[id]===true}}catch(e){}
let activeArea='';
function updateProgress(){const n=[...validIds].filter(id=>completed[id]).length;$('progress').value=n;$('progress-text').textContent=n+' / 40 unidades completadas';}
function applyFilters(){const q=norm($('lesson-search').value);const status=$('lesson-status').value;let n=0;lessons.forEach(el=>{const matches=(!activeArea||el.dataset.area===activeArea)&&norm(el.textContent).includes(q)&&(!status||(status==='done'?!!completed[el.id]:!completed[el.id]));el.hidden=!matches;if(matches)n++;});document.querySelectorAll('.area-group').forEach(g=>g.hidden=![...g.querySelectorAll('.lesson')].some(el=>!el.hidden));$('result-count').textContent=n+' de 40 unidades visibles';$('no-results').hidden=n>0;}
lessons.forEach(el=>{const check=el.querySelector('[data-done]');check.checked=!!completed[el.id];el.classList.toggle('complete',check.checked);check.addEventListener('change',()=>{completed[el.id]=check.checked;el.classList.toggle('complete',check.checked);try{localStorage.setItem('atlas-course-progress-v1',JSON.stringify(completed))}catch(e){}updateProgress();applyFilters();});});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{activeArea=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));applyFilters();}));
$('lesson-search').addEventListener('input',applyFilters);$('lesson-status').addEventListener('change',applyFilters);
function openFromHash(){let id;try{id=decodeURIComponent(location.hash.slice(1))}catch(e){return}if(!validIds.has(id))return;activeArea='';$('lesson-search').value='';$('lesson-status').value='';document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='')));applyFilters();const el=$(id);el.open=true;requestAnimationFrame(()=>el.scrollIntoView({block:'start'}));}
window.addEventListener('hashchange',openFromHash);updateProgress();applyFilters();openFromHash();
$('export').addEventListener('click',()=>{const payload={programa:'Atlas',version:1,fecha:new Date().toISOString(),completadas:[...validIds].filter(id=>completed[id])};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='atlas-progreso.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
const referenceEls=[...document.querySelectorAll('.reference')];function filterRefs(){const q=norm($('ref-search').value);let n=0;referenceEls.forEach(el=>{el.hidden=!norm(el.textContent).includes(q);if(!el.hidden)n++});$('ref-count').textContent=n+' referencias visibles';$('no-refs').hidden=n>0;}$('ref-search').addEventListener('input',filterRefs);filterRefs();
const number=id=>Number($(id).value),pct=x=>(100*x).toFixed(2)+'%';
function bayes(prevalence,sensitivity,specificity){const tp=prevalence*sensitivity,fp=(1-prevalence)*(1-specificity);return tp+fp>0?tp/(tp+fp):null;}
function decision(gain,loss,p){return{expected:gain*(1-p)-loss*p,threshold:gain/(gain+loss)}}
function bh(values,q){const sorted=values.map((p,i)=>({p,i})).sort((a,b)=>a.p-b.p);let k=0;sorted.forEach((v,i)=>{if(v.p<=(i+1)*q/sorted.length)k=i+1});return sorted.slice(0,k).map(v=>v.i+1);}
function bindForm(id,fn){$(id).addEventListener('submit',event=>{event.preventDefault();if($(id).reportValidity())fn();});fn();}
bindForm('bayes-form',()=>{const p=number('prev')/100,s=number('sens')/100,c=number('spec')/100;const ppv=bayes(p,s,c);$('bayes-result').textContent=ppv===null?'Probabilidad posterior no definida: el modelo asigna probabilidad cero a un positivo.':'P(caso | positivo) = '+pct(ppv)+'. Por 10,000 observaciones: '+(10000*p*s).toFixed(1)+' verdaderos positivos y '+(10000*(1-p)*(1-c)).toFixed(1)+' falsos positivos esperados.';});
bindForm('join-form',()=>{const a=number('lines'),b=number('payments');$('join-result').textContent=(a*b).toLocaleString('es')+' filas. La suma de importes de líneas se repite '+b+' veces; la de pagos, '+a+' veces. Agrega cada relación a nivel factura antes de unir si ese es el grano buscado.';});
bindForm('decision-form',()=>{const r=decision(number('gain'),number('loss'),number('pd')/100);const action=Math.abs(r.expected)<1e-9?'Hay indiferencia bajo estos supuestos.':r.expected>0?'Aprobar supera a rechazar en este modelo.':'Rechazar supera a aprobar en este modelo.';$('decision-result').textContent='Utilidad esperada = '+r.expected.toFixed(2)+'. Umbral de indiferencia: '+pct(r.threshold)+'. '+action;});
bindForm('bh-form',()=>{const parts=$('pvalues').value.split(',').map(s=>s.trim());const values=parts.map(Number);if(parts.length>1000||parts.some(s=>s==='')||values.some(v=>!Number.isFinite(v)||v<0||v>1)){$('bh-result').textContent='Introduce entre 1 y 1,000 p-valores de 0 a 1, separados por coma y con punto decimal.';return}const selected=bh(values,number('q'));$('bh-result').textContent='Hipótesis declaradas por posición original (desde 1): '+(selected.length?selected.join(', '):'ninguna')+'. Total: '+selected.length+' de '+values.length+'.';});
bindForm('metrics-form',()=>{const tp=number('tp'),fp=number('fp'),fn=number('fn'),tn=number('tn');const ratio=(a,b)=>b>0?pct(a/b):'no definida';$('metrics-result').textContent='Precision: '+ratio(tp,tp+fp)+' · Recall: '+ratio(tp,tp+fn)+' · Especificidad: '+ratio(tn,tn+fp)+' · Accuracy: '+ratio(tp+tn,tp+fp+fn+tn)+'.';});
let printSnapshot=[];window.addEventListener('beforeprint',()=>{printSnapshot=[...document.querySelectorAll('details')].map(el=>[el,el.open]);document.querySelectorAll('details').forEach(el=>el.open=true)});window.addEventListener('afterprint',()=>{printSnapshot.forEach(([el,open])=>el.open=open)});
'''
